cd /home/node/.cache/github-dark-factory-agent/work/be9d3b2c-65e2-5dbc-a8d8-b94acb40c014
cat > /tmp/godoc-lock.awk <<'AWK'
function recv(line,   r,t,n,a) {
  match(line, /^func[ \t]+\([^)]*\)/)
  r = substr(line, RSTART, RLENGTH)
  sub(/^func[ \t]+\(/, "", r); sub(/\)$/, "", r)
  gsub(/^[ \t]+|[ \t]+$/, "", r)
  n = split(r, a, /[ \t]+/)
  t = a[n]; sub(/^\*/, "", t)
  return t
}
FNR==1 { prev="" }
/^func[ \t]+[A-Z]/ { n++; if (prev !~ /^[[:space:]]*\/\//) { print FILENAME ":" FNR ": " $0; bad=1 } }
/^func[ \t]+\(/ { if (recv($0) ~ /^[A-Z]/) { n++; if (prev !~ /^[[:space:]]*\/\//) { print FILENAME ":" FNR ": " $0; bad=1 } } }
/^(type|var|const)[ \t]+[A-Z]/ { n++; if (prev !~ /^[[:space:]]*\/\//) { print FILENAME ":" FNR ": " $0; bad=1 } }
{ prev=$0 }
END { printf "documented_exported=%d\n", n; exit (bad || n < 24) }
AWK
echo "=== run godoc lock ==="
awk -f /tmp/godoc-lock.awk $(find pkg cmd -name '*.go' -not -name '*_test.go' | sort) $(find . -maxdepth 1 -name '*.go' -not -name '*_test.go'); echo "exit=$?"
echo "=== run AC1 block (expect FAIL, not implemented) ==="
P=$(grep -n '^## Package layout' README.md | cut -d: -f1)
R=$(grep -n '^## Related' README.md | cut -d: -f1)
test "$(grep -c '^## Package layout' README.md)" -eq 1 && test -n "$P" && test -n "$R" && test "$P" -lt "$R" || { echo "FAIL: layout heading missing, duplicated, or after Related"; echo "exit=$?"; }
echo "=== CHANGELOG block ==="
grep -q '^## Unreleased' CHANGELOG.md && grep -A5 '^## Unreleased' CHANGELOG.md | grep -q 'Package layout' || { echo "FAIL: no Unreleased entry naming the package-layout section"; }
